class SquareMatrix {
    constructor(size, buf) {
        this.size = size;
        this.buf = buf || new Array(size * size).fill(null);
    }

    static zero(size, zeroVal) {
        return new SquareMatrix(size, new Array(size * size).fill(zeroVal()));
    }

    static identity(size, zeroVal, oneVal) {
        let e = SquareMatrix.zero(size, zeroVal);
        for (let i = 0; i < size; i++) {
            e.buf[i * size + i] = oneVal();
        }
        return e;
    }

    get(x, y) {
        if (!(x < this.size && y < this.size)) throw new Error("assert");
        return this.buf[x * this.size + y];
    }

    get_mut(x, y) {
        if (!(x < this.size && y < this.size)) throw new Error("assert");
        return x * this.size + y;
    }

    matadd(rhs, add) {
        if (this.size !== rhs.size) throw new Error("assert");
        let buf = new Array(this.buf.length);
        for (let i = 0; i < this.buf.length; i++) {
            buf[i] = add(this.buf[i], rhs.buf[i]);
        }
        return new SquareMatrix(this.size, buf);
    }

    matmul(rhs, zeroVal, add, mul) {
        let size = this.size;
        if (size !== rhs.size) throw new Error("assert");
        let res = SquareMatrix.zero(size, zeroVal);
        for (let row = 0; row < size; row++) {
            for (let col = 0; col < size; col++) {
                let val = zeroVal();
                for (let k = 0; k < size; k++) {
                    val = add(val, mul(this.buf[row * size + k], rhs.buf[k * size + col]));
                }
                res.buf[row * size + col] = val;
            }
        }
        return res;
    }

    mat_pow(n, zeroVal, oneVal, add, mul) {
        let size = this.size;
        let t = SquareMatrix.identity(size, zeroVal, oneVal);
        let s = new SquareMatrix(this.size, this.buf.slice());
        while (n > 0) {
            if ((n & 1) === 1) {
                t = t.matmul(s, zeroVal, add, mul);
            }
            s = s.matmul(s, zeroVal, add, mul);
            n >>= 1;
        }
        return t;
    }

    matsub(rhs, sub) {
        if (this.size !== rhs.size) throw new Error("assert");
        let buf = new Array(this.buf.length);
        for (let i = 0; i < this.buf.length; i++) {
            buf[i] = sub(this.buf[i], rhs.buf[i]);
        }
        return new SquareMatrix(this.size, buf);
    }
}
